const BEATS={"a1s1":[[2,"Archidamus fears Bohemia cannot match Sicilia's hospitality"],[9,"Camillo describes the kings' lifelong friendship"],[10,"Archidamus praises young Mamillius"],[14,"The old long to see the prince grown"]],"a1s2":[[18,"Polixenes, after nine months, says he must go home"],[26,"He refuses Leontes"],[34,"Hermione persuades him to stay"],[39,"Polixenes recalls a boyhood as innocent as lambs"],[50,"Hermione gives Polixenes her hand"],[52,"Leontes: 'Too hot, too hot!'"],[56,"He studies Mamillius's face for likeness"],[69,"Alone with his son, he imagines himself a cuckold"],[93,"He tells Camillo: 'Is whispering nothing?'"],[99,"He orders Camillo to poison Polixenes"],[109,"Camillo resolves to flee rather than kill a king"],[124,"He warns Polixenes"],[133,"They agree to escape that night"]],"a2s1":[[138,"Hermione asks for a tale"],[154,"Mamillius: 'A sad tale's best for winter'"],[163,"Leontes learns of the escape: 'I have drunk, and seen the spider'"],[170,"He accuses Hermione before the court"],[175,"She goes to prison with dignity"],[186,"Antigonus and the lords protest"],[193,"Leontes has sent to the oracle"]],"a2s2":[[200,"Paulina is refused entry to the queen"],[220,"Emilia: the queen has borne a daughter"],[221,"Paulina will take the baby to the king"],[226,"She persuades the gaoler"]],"a2s3":[[232,"Leontes cannot sleep"],[236,"Mamillius is ill with grief"],[244,"Paulina forces her way in"],[256,"She lays the baby before the king"],[268,"The baby is the copy of her father"],[274,"Paulina all but calls him a tyrant"],[278,"Leontes orders the baby burnt"],[282,"The lords kneel"],[287,"Antigonus must abandon the baby far away"],[294,"The messengers are back; a trial is called"]],"a3s1":[[298,"Cleomenes and Dion recall Delphi"],[300,"The oracle's thunderous voice"],[303,"They hurry on to court"]],"a3s2":[[307,"Leontes opens the trial"],[311,"The charges are read"],[312,"Hermione defends her honour"],[320,"She appeals to Apollo"],[328,"The oracle clears her"],[333,"Leontes calls it false"],[339,"Mamillius is dead"],[346,"Leontes repents"],[350,"Paulina: the queen is dead"],[356,"He vows to mourn every day"]],"a3s3":[[361,"A storm rises over Bohemia"],[367,"Antigonus tells his dream and names Perdita"],[369,"He leaves the baby and is chased off by a bear"],[374,"The Shepherd finds the baby"],[380,"The Clown describes the wreck and the bear"],[386,"They find gold"],[391,"'A lucky day'"]],"a4s1":[[395,"Time leaps sixteen years and introduces Florizel and Perdita"]],"a4s2":[[400,"Camillo longs to go home"],[401,"Polixenes begs him to stay"],[403,"Florizel visits a shepherd's house"],[405,"They will go in disguise"]],"a4s3":[[411,"Autolycus sings of spring"],[413,"The Clown plans the feast"],[416,"Autolycus pretends to be robbed"],[431,"He picks the Clown's pocket"],[437,"He blames 'Autolycus'"],[449,"He heads for the sheep-shearing"]],"a4s4":[[455,"Florizel praises Perdita as Flora"],[458,"Perdita fears his father"],[466,"She gives flowers to the disguised guests"],[471,"Nature and art: the grafting debate"],[476,"Spring flowers for the young"],[479,"Florizel's praise; they dance"],[483,"Polixenes: she is 'Too noble for this place'"],[507,"Autolycus sells his wares"],[537,"A three-part song"],[564,"Polixenes questions Florizel"],[574,"The Shepherd agrees to the betrothal"],[591,"Polixenes unmasks"],[593,"He threatens them all"],[595,"Perdita: the same sun shines on both"],[604,"Florizel will not give her up"],[619,"Camillo sends them to Sicilia"],[650,"Florizel and Autolycus swap clothes"],[660,"Camillo will bring Polixenes after them"],[685,"Autolycus poses as a courtier"],[705,"He terrifies the Shepherd and Clown"],[718,"He takes them to the prince's ship"]],"a5s1":[[722,"Cleomenes urges Leontes to forgive himself"],[724,"Paulina keeps his grief alive"],[729,"She recalls the oracle"],[738,"Leontes swears not to remarry without her leave"],[747,"Florizel and his princess arrive"],[762,"Leontes welcomes them"],[770,"Polixenes is in the city"],[779,"The lovers are not married"],[786,"Leontes will plead for them"]],"a5s2":[[791,"A gentleman saw the bundle opened"],[796,"'The oracle is fulfilled'"],[799,"The proofs of Perdita's birth"],[801,"The meeting of the kings"],[803,"The fate of Antigonus"],[809,"Everyone goes to see Hermione's statue"],[817,"The Shepherd and Clown are gentlemen now"],[828,"The Clown will swear to Autolycus's honesty"]],"a5s3":[[840,"Leontes asks to see the statue"],[843,"Paulina reveals it"],[844,"It is wrinkled, as she would be now"],[847,"Leontes: 'does not the stone rebuke me'"],[848,"Perdita kneels to it"],[861,"Leontes longs to kiss it"],[867,"'Awake your faith'"],[869,"Hermione steps down"],[872,"'O, she's warm!'"],[878,"Hermione blesses her daughter"],[880,"Leontes pairs Paulina with Camillo and asks pardon"]]};
